alter table public.profiles enable row level security;
alter table public.posts enable row level security;
alter table public.post_comments enable row level security;
alter table public.post_likes enable row level security;
alter table public.comment_likes enable row level security;
alter table public.article_likes enable row level security;
alter table public.snippet_likes enable row level security;
alter table public.articles enable row level security;
alter table public.article_comments enable row level security;
alter table public.snippets enable row level security;
alter table public.resources enable row level security;
alter table public.topics enable row level security;
alter table public.hot_searches enable row level security;
alter table public.notifications enable row level security;
alter table public.messages enable row level security;
alter table public.favorites enable row level security;
alter table public.follows enable row level security;
alter table public.post_drafts enable row level security;
alter table public.article_drafts enable row level security;
alter table public.documents enable row level security;
alter table public.roles enable row level security;
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.user_roles enable row level security;
alter table public.audit_logs enable row level security;
create policy profiles_select on public.profiles for select using (true);
create policy profiles_insert on public.profiles for insert with check (id = auth.uid());
create policy profiles_update on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy posts_select on public.posts for select using (true);
create policy posts_insert on public.posts for insert with check (author_id = auth.uid());
create policy posts_update on public.posts for update using (author_id = auth.uid()) with check (author_id = auth.uid());
create policy posts_delete on public.posts for delete using (author_id = auth.uid());
create policy articles_select on public.articles for select using (true);
create policy articles_insert on public.articles for insert with check (author_id = auth.uid());
create policy articles_update on public.articles for update using (author_id = auth.uid()) with check (author_id = auth.uid());
create policy articles_delete on public.articles for delete using (author_id = auth.uid());
create policy snippets_select on public.snippets for select using (true);
create policy snippets_insert on public.snippets for insert with check (author_id = auth.uid());
create policy snippets_update on public.snippets for update using (author_id = auth.uid()) with check (author_id = auth.uid());
create policy snippets_delete on public.snippets for delete using (author_id = auth.uid());
create policy post_comments_select on public.post_comments for select using (true);
create policy post_comments_insert on public.post_comments for insert with check (author_id = auth.uid());
create policy post_comments_delete on public.post_comments for delete using (author_id = auth.uid());
create policy article_comments_select on public.article_comments for select using (true);
create policy article_comments_insert on public.article_comments for insert with check (author_id = auth.uid());
create policy article_comments_delete on public.article_comments for delete using (author_id = auth.uid());
create policy post_likes_all on public.post_likes for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy comment_likes_all on public.comment_likes for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy article_likes_all on public.article_likes for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy snippet_likes_all on public.snippet_likes for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy favorites_all on public.favorites for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy follows_all on public.follows for all using (follower_id = auth.uid()) with check (follower_id = auth.uid());
create policy notifications_select on public.notifications for select using (user_id = auth.uid());
create policy notifications_insert on public.notifications for insert with check (from_user_id = auth.uid());
create policy notifications_update on public.notifications for update using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy notifications_delete on public.notifications for delete using (user_id = auth.uid());
create policy messages_select on public.messages for select using (owner_id = auth.uid());
create policy messages_update on public.messages for update using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy messages_delete on public.messages for delete using (owner_id = auth.uid());
create policy post_drafts_all on public.post_drafts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy article_drafts_all on public.article_drafts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy documents_all on public.documents for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy roles_select on public.roles for select using (auth.role() = 'authenticated');
create policy permissions_select on public.permissions for select using (auth.role() = 'authenticated');
create policy role_permissions_select on public.role_permissions for select using (auth.role() = 'authenticated');
create policy user_roles_select on public.user_roles for select using (user_id = auth.uid());
create policy audit_logs_select on public.audit_logs for select using (exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id where ur.user_id = auth.uid() and r.name = 'admin'));
create policy resources_select on public.resources for select using (true);
create policy topics_select on public.topics for select using (true);
create policy hot_searches_select on public.hot_searches for select using (true);
create or replace function public.bump_post_likes() returns trigger language plpgsql security definer set search_path = public as $f$ begin if (tg_op = 'INSERT') then update public.posts set likes = likes + 1 where id = new.post_id; elsif (tg_op = 'DELETE') then update public.posts set likes = greatest(0, likes - 1) where id = old.post_id; end if; return null; end $f$;
drop trigger if exists post_likes_count on public.post_likes;
create trigger post_likes_count after insert or delete on public.post_likes for each row execute function public.bump_post_likes();
create or replace function public.bump_comment_likes() returns trigger language plpgsql security definer set search_path = public as $f$ begin if (tg_op = 'INSERT') then update public.post_comments set likes = likes + 1 where id = new.comment_id; elsif (tg_op = 'DELETE') then update public.post_comments set likes = greatest(0, likes - 1) where id = old.comment_id; end if; return null; end $f$;
drop trigger if exists comment_likes_count on public.comment_likes;
create trigger comment_likes_count after insert or delete on public.comment_likes for each row execute function public.bump_comment_likes();
create or replace function public.bump_article_likes() returns trigger language plpgsql security definer set search_path = public as $f$ begin if (tg_op = 'INSERT') then update public.articles set likes = likes + 1 where id = new.article_id; elsif (tg_op = 'DELETE') then update public.articles set likes = greatest(0, likes - 1) where id = old.article_id; end if; return null; end $f$;
drop trigger if exists article_likes_count on public.article_likes;
create trigger article_likes_count after insert or delete on public.article_likes for each row execute function public.bump_article_likes();
create or replace function public.bump_snippet_likes() returns trigger language plpgsql security definer set search_path = public as $f$ begin if (tg_op = 'INSERT') then update public.snippets set likes = likes + 1 where id = new.snippet_id; elsif (tg_op = 'DELETE') then update public.snippets set likes = greatest(0, likes - 1) where id = old.snippet_id; end if; return null; end $f$;
drop trigger if exists snippet_likes_count on public.snippet_likes;
create trigger snippet_likes_count after insert or delete on public.snippet_likes for each row execute function public.bump_snippet_likes();
create or replace function public.bump_follow_counts() returns trigger language plpgsql security definer set search_path = public as $f$ begin if (tg_op = 'INSERT') then update public.profiles set following = following + 1 where id = new.follower_id; update public.profiles set followers = followers + 1 where id = new.followee_id; elsif (tg_op = 'DELETE') then update public.profiles set following = greatest(0, following - 1) where id = old.follower_id; update public.profiles set followers = greatest(0, followers - 1) where id = old.followee_id; end if; return null; end $f$;
drop trigger if exists follows_count on public.follows;
create trigger follows_count after insert or delete on public.follows for each row execute function public.bump_follow_counts();
create or replace function public.send_message(p_peer text, p_content text) returns void language plpgsql security definer set search_path = public as $f$ declare me text := auth.uid(); msg_id text := 'm' || replace(gen_random_uuid()::text, '-', ''); begin if me is null or me = p_peer or coalesce(trim(p_content), '') = '' then raise exception 'invalid message'; end if; insert into public.messages (id, owner_id, peer_id, from_me, content, read) values (msg_id, me, p_peer, true, p_content, true); insert into public.messages (id, owner_id, peer_id, from_me, content, read) values (msg_id, p_peer, me, false, p_content, false); end $f$;
create or replace function public.bump_article_views(p_id text) returns int language sql security definer set search_path = public as $f$ update public.articles set views = views + 1 where id = p_id returning views; $f$;
grant execute on function public.send_message(text, text) to authenticated;
grant execute on function public.bump_article_views(text) to anon, authenticated;
